Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

static int buffer_resize_should_fail = 0;
static int (*real_buffer_resize)(buffer_t *, size_t) = NULL;

// Mock buffer_resize to simulate failure
int mock_buffer_resize(buffer_t *self, size_t n) {
    if (buffer_resize_should_fail) {
        return -1;
    }
    return real_buffer_resize(self, n);
}

extern int buffer_resize(buffer_t *self, size_t n);

// Redirect buffer_resize to our mock
#define buffer_resize mock_buffer_resize

void setUp(void) {
    // Save the real buffer_resize function pointer if not already saved
    if (!real_buffer_resize) {
        real_buffer_resize = buffer_resize;
    }
    buffer_resize_should_fail = 0;
}

void tearDown(void) {
    buffer_resize_should_fail = 0;
}

void unit_test_buffer_append_n_resize_fails(void) {
    // Setup: create a buffer with small capacity and known data
    buffer_t *buf = helper_make_buffer_with_data("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // Shrink the buffer's capacity to force a resize
    buf->len = 4; // Only enough for "abc" + '\0'

    // Prepare string to append
    const char *to_append = "XYZ";
    size_t append_len = 3;

    // Save original buffer state for later comparison
    char original_data[16];
    strncpy(original_data, buf->data, sizeof(original_data));
    original_data[sizeof(original_data)-1] = '\0';
    size_t original_length = strlen(buf->data);
    size_t original_size = buf->len;

    // Simulate buffer_resize failure
    buffer_resize_should_fail = 1;

    // Test: attempt to append, expecting failure
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assertions
    TEST_ASSERT_EQUAL_INT(-1, ret);
    helper_assert_buffer_data_equals(buf, original_data);
    helper_assert_buffer_length(buf, original_length);
    helper_assert_buffer_size(buf, original_size);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_fails);
    return UNITY_END();
}

